import math,re
def r(v,a,b,deg):
    t=math.radians(deg);c,s=math.cos(t),math.sin(t);v=list(v);u,w=v[a],v[b]
    v[a]=round(c*u-s*w);v[b]=round(s*u+c*w);return tuple(v)
XZ=lambda v,d:r(v,0,2,d);XY=lambda v,d:r(v,0,1,d);YZ=lambda v,d:r(v,1,2,d)
def rot(v,fd):
    ax,f=fd>>2,fd&3
    if ax==0: v=XZ(v,{0:0,1:-90,2:180,3:90}[f])
    elif ax==1: v=YZ(v,90); v=XY(v,{0:0,1:90,2:180,3:-90}[f])
    elif ax==2: v=YZ(v,-90); v=XY(v,{0:0,1:-90,2:180,3:90}[f])
    elif ax==3: v=XY(v,-90); v=YZ(v,{0:0,1:90,2:180,3:-90}[f])
    elif ax==4: v=XY(v,90); v=YZ(v,{0:0,1:-90,2:180,3:90}[f])
    else: v=XY(v,-180); v=XZ(v,{0:0,1:90,2:180,3:-90}[f])
